def transform(grid):
    if not grid or not grid[0]:
        return []

    # Context color (background) - use corner value
    bg_color = grid[0][0]
    rows = len(grid)
    cols = len(grid[0])

    # Find all connected components of the target color (appears multiple times)
    from collections import deque

    visited = [[False]*cols for _ in range(rows)]
    component_shapes = []  # List of (dimensions, shape_tuple, canonical_key)

    # Scan for non-background connected components
    target_colors = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg_color:
                target_colors.add(grid[r][c])

    for target in target_colors:
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == target and not visited[r][c]:
                    # BFS to find connected component
                    component = []
                    queue = deque([(r, c)])
                    visited[r][c] = True

                    while queue:
                        cr, cc = queue.popleft()
                        component.append((cr, cc))
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = cr+dr, cc+dc
                            if 0 <= nr < rows and 0 <= nc < cols:
                                if not visited[nr][nc] and grid[nr][nc] == target:
                                    visited[nr][nc] = True
                                    queue.append((nr, nc))

                    # Convert to canonical shape with offset
                    min_r, min_c = min(component, key=lambda p: p[0])
                    max_r = max(p[0] for p in component)
                    max_c = min_c + max(p[1] - min_c for p in component)

                    shape = []
                    for sec_r in range(max_r - min_r + 1):
                        row = []
                        for sec_c in range(max_c - min_c + 1):
                            orig_r, orig_c = min_r + sec_r, min_c + sec_c
                            if (orig_r, orig_c) in component:
                                row.append(target)
                            else:
                                row.append(bg_color)
                        shape.append(row)

                    shape_key = tuple(map(tuple, shape))
                    component_shapes.append((shape_key, shape))

    if not component_shapes:
        return [[0]]

    # Find the most common shape
    from collections import Counter
    shape_counts = Counter(shape[0] for shape in component_shapes)
    most_common_key = shape_counts.most_common(1)[0][0]

    # Return the unique shape
    for shape in component_shapes:
        if shape[0] == most_common_key:
            return shape[1]

    return component_shapes[0][1]
